var cleaned = await session.RunAsync("Clean up the temp folder", new RunOptions
{
    OnApproval = approval =>
    {
        if (approval.IsLinkOnly)
        {
            Console.WriteLine($"Approve in a browser: {approval.Url}");
            return null; // a person answers it; keep waiting
        }
        if (approval.Type == "choice")
        {
            var selections = approval.Questions
                .Select(q => new[] { q.GetProperty("options")[0].GetProperty("value").GetString()! })
                .ToArray();
            return new ApprovalAnswer("yes", selections);
