snippets.code:
var job = await sai.Learn.CreateAsync([], new LearnOptions
{
    TaskTemplate =
        "Open {{newsSite}}, find all {{topic}} news published today, write their headlines into Notepad, one per line, and save the file as {{fileName}}",
    Inputs = new Dictionary<string, object> { ["newsSite"] = "TechCrunch", ["topic"] = "AI", ["fileName"] = "techcrunch_headlines.txt" },
    Machine = pc,
    Criteria =
        "techcrunch_headlines.txt is saved and holds, one per line, the headlines of the AI articles TechCrunch published today",
    MaxIterations = 3, // up to 3 code versions; 0 (the default) only writes the code
    Rollouts = 3, // each version must pass 3 runs in a row
    Reset = Reset.Code("""
        for (const t of await machine.browser.listTabs()) await machine.browser.closeTab(t.tabId)
        for (const w of await machine.getWindow("Notepad")) await w.close()
        """),
    ContinueWithAgent = true, // after a failed run, the agent finishes the task and the repair learns from it
});
var done = await sai.Learn.WaitAsync(job); // can take an hour; pass timeout: to stop waiting
Console.WriteLine($"{done.Status} {done.StopReason} {done.TestResult}");
Console.WriteLine(done.Code); // the latest version
foreach (var it in done.Iterations)
{
    Console.WriteLine($"{it.Index} {it.Changes} {string.Join(", ", it.Rollouts.Select(x => x.Verdict))}");
}

var run = await sai.Learn.RolloutAsync(job, 1, 1); // what one run returned and logged, and its judgement
await sai.Learn.CancelAsync(job); // stops at once and keeps the last complete results

